# Edit this list. A run can also pass {"repos": ["owner/name"]} as its input.
REPOS = ["octocat/Hello-World"]

from datetime import datetime, timedelta, timezone


def main(input_data):
    repos = REPOS
    if isinstance(input_data, dict) and input_data.get("repos"):
        repos = input_data["repos"]
    since = (datetime.now(timezone.utc) - timedelta(days=1)).strftime("%Y-%m-%d")
    q = " ".join("repo:" + r for r in repos) + " updated:>=" + since
    return {"q": q, "since": since}

def main(input_data):
    body = input_data.get("body") or {}
    items = body.get("items", []) if isinstance(body, dict) else []
    lines = []
    for it in items:
        repo = it["repository_url"].split("/repos/")[-1]
        kind = "PR" if "pull_request" in it else "issue"
        labels = ", ".join(label["name"] for label in it.get("labels", []))
        extra = ", labels: " + labels if labels else ""
        lines.append(
            "- [%s] %s#%s %s (by %s, %s%s)"
            % (kind, repo, it["number"], it["title"], it["user"]["login"], it["state"], extra)
        )
    return {"count": len(lines), "digest": "\n".join(lines)}

from datetime import datetime


def main(input_data):
    text = next(iter(input_data.values()))["text"]
    stamp = datetime.now().astimezone().strftime("%Y-%m-%d %H:%M")
    return {"text": "## " + stamp + "\n\n" + text.strip() + "\n\n---\n\n"}
